export async function createScene(engine, canvas, BABYLON) {
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.76, 0.76, 0.76);

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.1, 0, -0.5));
  camera.alpha = -1.95;
  camera.beta = 0.65;
  camera.radius = 10;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  const light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.7;

  const ground = BABYLON.MeshBuilder.CreateGround("ground", { width: 6, height: 6 }, scene);
  ground.showBoundingBox = true;

  let heatmapData = [];
  let heatmapTexture = null;
  let interval = 30;

  const HEATMAP_WIDTH = 512;
  const HEATMAP_HEIGHT = 512;
  const HEAT_RADIUS = 30;
  const HEAT_INTENSITY = 0.1;

  for (let y = 0; y < HEATMAP_HEIGHT; y++) {
    heatmapData[y] = new Array(HEATMAP_WIDTH).fill(0);
  }

  heatmapTexture = new BABYLON.DynamicTexture("heatmapTex", { width: HEATMAP_WIDTH, height: HEATMAP_HEIGHT }, scene);

  const groundMat = new BABYLON.StandardMaterial("groundMat", scene);
  groundMat.diffuseTexture = heatmapTexture;
  groundMat.emissiveTexture = heatmapTexture;
  groundMat.emissiveColor = new BABYLON.Color3(0.27, 0.27, 0.27);
  ground.material = groundMat;

  updateHeatmapTexture();

  function throttle(func, limit) {
    let inThrottle;
    return function (...args) {
      if (!inThrottle) {
        func.apply(this, args);
        inThrottle = true;
        setTimeout(() => (inThrottle = false), limit);
      }
    };
  }

  const throttledAddHeatPoint = throttle((x, y) => {
    addHeatPoint(x, y);
    updateHeatmapTexture();
  }, interval);

  scene.onPointerObservable.add((pointerInfo) => {
    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERDOWN || pointerInfo.type === BABYLON.PointerEventTypes.POINTERMOVE) {
      const pickResult = scene.pick(scene.pointerX, scene.pointerY);

      if (pickResult.hit && pickResult.pickedMesh === ground) {
        const uv = pickResult.getTextureCoordinates();
        if (uv) {
          const x = Math.floor(uv.x * HEATMAP_WIDTH);
          const y = Math.floor(uv.y * HEATMAP_HEIGHT);

          throttledAddHeatPoint(x, y);
        }
      }
    }
  });

  function getHeatmapColor(value) {
    if (value === 0) return [0, 0, 0, 0];
    let t = Math.min(Math.max(value, 0), 1);
    if (t < 0.25) {
      let g = Math.floor(255 * (t / 0.25));
      return [0, g, 255, Math.floor(t * 255)];
    } else if (t < 0.5) {
      let b = Math.floor(255 * (1 - (t - 0.25) / 0.25));
      return [0, 255, b, Math.floor(t * 255)];
    } else if (t < 0.75) {
      let r = Math.floor(255 * ((t - 0.5) / 0.25));
      return [r, 255, 0, Math.floor(t * 255)];
    } else {
      let g = Math.floor(255 * (1 - (t - 0.75) / 0.25));
      return [255, g, 0, Math.floor(t * 255)];
    }
  }

  function updateHeatmapTexture() {
    const ctx = heatmapTexture.getContext();
    const imgData = ctx.createImageData(HEATMAP_WIDTH, HEATMAP_HEIGHT);
    for (let y = 0; y < HEATMAP_HEIGHT; y++) {
      for (let x = 0; x < HEATMAP_WIDTH; x++) {
        const val = heatmapData[y][x];
        const color = getHeatmapColor(val);

        const index = (y * HEATMAP_WIDTH + x) * 4;
        imgData.data[index] = color[0]; // R
        imgData.data[index + 1] = color[1]; // G
        imgData.data[index + 2] = color[2]; // B
        imgData.data[index + 3] = color[3]; // A
      }
    }
    ctx.putImageData(imgData, 0, 0);
    heatmapTexture.update(false);
  }

  function addHeatPoint(centerX, centerY) {
    for (let y = 0; y < HEATMAP_HEIGHT; y++) {
      for (let x = 0; x < HEATMAP_WIDTH; x++) {
        const dx = x - centerX;
        const dy = y - centerY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist <= HEAT_RADIUS) {
          const intensity = HEAT_INTENSITY * Math.exp(-(dist * dist) / (2 * (HEAT_RADIUS / 3) * (HEAT_RADIUS / 3)));
          heatmapData[y][x] = Math.min(heatmapData[y][x] + intensity, 1);
        }
      }
    }
    updateHeatmapTexture();
  }

  const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  const rect = new BABYLON.GUI.Rectangle("root");
  rect.width = "150px";
  rect.height = "80px";
  rect.adaptHeightToChildren = true;
  rect.thickness = 0;
  rect.background = "#ebebed";
  rect.cornerRadius = 10;
  rect.top = "10px";
  rect.left = "10px";
  rect.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  rect.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  advancedTexture.addControl(rect);

  const panel = new BABYLON.GUI.StackPanel();
  panel.width = "150px";
  panel.height = "80px";
  panel.paddingTop = "2.5px";
  panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  rect.addControl(panel);

  const header = new BABYLON.GUI.TextBlock();
  header.text = "HeatMap";
  header.height = "30px";
  header.color = "black";
  header.fontSize = 20;
  panel.addControl(header);

  const clearBtn = BABYLON.GUI.Button.CreateSimpleButton("clear", "Reset");
  clearBtn.width = "100px";
  clearBtn.height = "40px";
  clearBtn.color = "white";
  clearBtn.background = "red";
  clearBtn.cornerRadius = 8;
  clearBtn.paddingTop = "10px";
  clearBtn.onPointerUpObservable.add(() => {
    for (let y = 0; y < HEATMAP_HEIGHT; y++) {
      heatmapData[y].fill(0);
    }
    updateHeatmapTexture();
  });
  panel.addControl(clearBtn);

  const rect2 = new BABYLON.GUI.Rectangle("root");
  rect2.width = "250px";
  rect2.height = "80px";
  rect2.adaptHeightToChildren = true;
  rect2.thickness = 0;
  rect2.background = "#ebebed";
  rect2.cornerRadius = 10;
  rect2.top = "-10px";
  rect2.left = "10px";
  rect2.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  rect2.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_BOTTOM;
  advancedTexture.addControl(rect2);

  const panel2 = new BABYLON.GUI.StackPanel();
  panel2.width = "250px";
  panel2.height = "80px";
  panel2.paddingTop = "2.5px";
  panel2.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
  panel2.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
  rect2.addControl(panel2);

  const header2 = new BABYLON.GUI.TextBlock();
  header2.text = "Color Scheme";
  header2.height = "30px";
  header2.color = "black";
  header2.fontSize = 20;
  panel2.addControl(header2);

  const panel3 = new BABYLON.GUI.StackPanel();
  panel3.isVertical = false;
  panel3.width = "220px";
  panel3.height = "40px";
  panel3.left = "3px";
  panel3.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_CENTER;
  panel3.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
  panel2.addControl(panel3);

  const header3 = new BABYLON.GUI.TextBlock();
  header3.width = "40px";
  header3.text = "Low";
  header3.height = "30px";
  header3.color = "black";
  header3.fontSize = 15;
  header3.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  panel3.addControl(header3);

  const colorBar = new BABYLON.GUI.Image("colorBar", "/images/textures/color_scheme.png");
  colorBar.width = "130px";
  colorBar.height = "30px";

  console.log(colorBar);
  console.log(colorBar instanceof BABYLON.GUI.Control);
  console.log(typeof colorBar._link);
  panel3.addControl(colorBar);

  const header4 = new BABYLON.GUI.TextBlock();
  header4.width = "40px";
  header4.text = "High";
  header4.height = "30px";
  header4.color = "black";
  header4.fontSize = 15;
  header4.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT;

  panel3.addControl(header4);

  return scene;
}
